Algorithm Buscar
  Dimension v[5] As Integer;
  For i <- 0 To 4 Do
    Read v[i];
  EndFor
  Define buscado As Integer;
  Read buscado;
  Define posicion As Integer <- -1;
  For i <- 0 To 4 Do
    If v[i] = buscado Then
      posicion <- i;
      Break;
    EndIf
  EndFor
  Write posicion;
EndAlgorithm

